# Study Map, Domain 2: Vulnerability Management. Original prose, written against
# the CS0-003 objectives. Shape: see sm_page.py.

def I(t, what, does, where='', full='', trap='', flow=None, kids=None):
    return dict(t=t, what=what, does=does, where=where, full=full, trap=trap, flow=flow, kids=kids or [])

OBJ = {}

OBJ['2.1'] = {'title': 'Given a scenario, implement vulnerability scanning methods and concepts.', 'items': [
I('Asset discovery',
  'Finding every device, service and application you own before you scan it for weaknesses.',
  'Builds the inventory that scanning, patching and risk scoring depend on. You can&rsquo;t protect what you don&rsquo;t know exists.',
  'Discovery runs from a scanner on the network, from agents on hosts, and from cloud provider APIs that list instances.',
  trap='Asset discovery comes first. A question asking for the first step of a vulnerability program usually wants an inventory, not a scan.',
  kids=[
  I('Map scans', 'A sweep across address ranges to find which hosts are alive and which ports they have open.',
    'Draws a map of the network: live IPs, open ports, running services.', 'Run from a scanner host, for example <code>nmap -sn 10.0.0.0/24</code> for live hosts only.'),
  I('Device fingerprinting', 'Working out what a device is (OS, vendor, version) from how it answers probes.',
    'Compares responses such as TTL values, TCP window sizes and service banners against known patterns.', 'Nmap <code>-O</code> (OS) and <code>-sV</code> (service versions); the MAC vendor prefix (OUI) also hints at the maker.'),
  ]),
I('Special considerations',
  'The business limits you plan scans around so a scan doesn&rsquo;t cause the outage it is meant to prevent.',
  'Decides when, how hard and where you scan, and what rules you must follow.',
  kids=[
  I('Scheduling', 'Choosing when scans run.', 'Puts heavy scans in quiet hours or maintenance windows and sets how often each asset class is scanned.'),
  I('Operations', 'The effect a scan has on day-to-day work.', 'Avoids scans that interrupt production, for example by locking accounts or crashing fragile services.'),
  I('Performance', 'The load a scan puts on hosts and the network.', 'Throttles scan speed and concurrent hosts so links and servers stay responsive.'),
  I('Sensitivity levels', 'How aggressive the scan&rsquo;s checks are.', 'Higher sensitivity finds more but adds false positives and risk; lowering it reduces noise.',
    trap='Too many false positives? Lower the sensitivity, then validate what remains.'),
  I('Segmentation', 'Networks split into zones by firewalls and VLANs.', 'Means one scanner may not reach every zone, so you place scanners or agents inside each segment.'),
  I('Regulatory requirements', 'Rules from laws and standards that set scanning duties.', 'Can require a schedule and a scan type; PCI DSS, for example, requires quarterly internal and external scans and an approved scanning vendor (ASV) for the external ones.'),
  ]),
I('Internal vs. external scanning',
  'Internal scans run from inside your network; external scans come from the internet toward your public addresses.',
  'Internal shows what an insider or an attacker who already got in could reach. External shows what anyone online can see.',
  flow=['Internet scanner', '*Firewall / public IPs', 'Internal network', 'Internal scanner'],
  trap='An external scan only sees what the firewall exposes. Missing internal findings in an external report is expected, not a failure.'),
I('Agent vs. agentless',
  'Agent scanning installs software on each host; agentless scanning probes hosts over the network.',
  'Agents report from inside the host even when it is off the network (laptops, remote sites, cloud). Agentless needs nothing installed but only sees what the network exposes.',
  'Agents live on the endpoint and report to a management server. Agentless scans run from a central scanner.',
  trap='Remote laptops, limited bandwidth or hosts that are rarely on the corporate network point to agent-based scanning.'),
I('Credentialed vs. non-credentialed',
  'A credentialed scan logs in to the target; a non-credentialed scan only looks from the outside.',
  'Credentialed scans see installed software, patch levels and settings, so they find more with fewer false positives. Non-credentialed scans show the attacker&rsquo;s view and use fewer resources.',
  'Credentials are stored in the scanner (Nessus, OpenVAS) and used over SMB/WMI on Windows or SSH on Linux.',
  trap='Your scan finds far more than someone else&rsquo;s scan of the same hosts? Yours was credentialed.'),
I('Passive vs. active',
  'Active scanning sends probes to targets. Passive scanning only listens to traffic that is already flowing.',
  'Active finds more but can disrupt fragile devices. Passive is safe for sensitive networks but only sees what talks.',
  'Passive sensors sit on a SPAN port or network tap.',
  trap='For ICS and SCADA, prefer passive monitoring; active scans can crash controllers.'),
I('Static vs. dynamic',
  'Static analysis examines code or a file without running it. Dynamic analysis runs it and watches what happens.',
  'Static finds flaws early and points to the exact line. Dynamic finds runtime and configuration problems the code alone doesn&rsquo;t show.',
  kids=[
  I('Reverse engineering', 'Taking compiled software or malware apart to understand how it works.', 'Shows hidden behavior, flaws or indicators when you have no source code.', 'Done with disassemblers and debuggers (Ghidra, IDA, GDB, Immunity Debugger) in an isolated lab.'),
  I('Fuzzing', 'Sending large amounts of malformed or random input to a program.', 'Triggers crashes and unexpected behavior that reveal input-handling bugs such as buffer overflows and injection.', 'Runs against a test copy of the app; Burp Intruder and ZAP Fuzzer do it for web apps.'),
  ]),
I('Critical infrastructure',
  'Systems that run physical processes: power, water, manufacturing, transport.',
  'Needs special care because an outage affects safety and the physical world, and many devices are old and fragile.',
  kids=[
  I('Operational technology (OT)', 'Hardware and software that monitors and controls physical equipment.', 'Keeps machines and processes running; availability and safety come before confidentiality.', 'On plant floors and field sites, ideally separated from the IT network.'),
  I('Industrial control systems (ICS)', 'The control side of OT: PLCs, HMIs and the networks connecting them.', 'Turns sensor readings into commands that open valves or start motors.', 'Uses industrial protocols such as Modbus and DNP3, which have little or no built-in security.'),
  I('Supervisory control and data acquisition (SCADA)', 'An ICS that supervises equipment spread over large areas.', 'Collects data from remote sites and sends commands from a central control room.', 'Pipelines, power grids and water systems, linked over long-distance networks.',
    trap='Scanning SCADA or ICS: active scans can disrupt them and standard tools miss OT flaws. Scan carefully or passively.'),
  ]),
I('Security baseline scanning',
  'Checking systems against an approved secure configuration.',
  'Reports every setting that drifted from the baseline: weak passwords allowed, unneeded services, missing hardening.',
  'Baselines come from CIS Benchmarks or internal standards; SCAP-based tools automate the check.'),
I('Industry frameworks',
  'Published standards that tell you what to scan for and how secure systems should be.',
  'Give scans a yardstick and give audits something to measure against.',
  kids=[
  I('PCI DSS', 'The card industry&rsquo;s security standard for anyone storing, processing or sending cardholder data.', 'Requires quarterly internal and external scans, external ones by an approved scanning vendor, plus rescans after fixes.', full='Payment Card Industry Data Security Standard'),
  I('CIS benchmarks', 'Free, consensus-built hardening guides for operating systems, cloud and applications.', 'Give exact recommended settings that baseline scans compare against.', full='Center for Internet Security'),
  I('OWASP', 'A nonprofit focused on web application security.', 'Publishes the Top 10 web risks, the Testing Guide, ASVS and the ZAP scanner.', full='Open Web Application Security Project (now Open Worldwide)'),
  I('ISO 27000 series', 'International standards for running an information security management system.', 'ISO 27001 sets the certifiable requirements; ISO 27002 lists the controls, including vulnerability management.', full='International Organization for Standardization'),
  ]),
]}

OBJ['2.2'] = {'title': 'Given a scenario, analyze output from vulnerability assessment tools.', 'items': [
I('Network scanning and mapping', 'Tools that find hosts and the relationships between them.', 'Show what is on the network and how it connects, before deeper testing.', kids=[
  I('Angry IP Scanner', 'A fast, free GUI scanner for IP ranges.', 'Lists live hosts, hostnames and open ports quickly.', 'Runs on the analyst&rsquo;s workstation (Windows, Linux, macOS).'),
  I('Maltego', 'An OSINT link-analysis tool.', 'Draws graphs connecting domains, people, emails and infrastructure from public data.', 'A desktop app pulling from online data sources ("transforms").'),
  ]),
I('Web application scanners', 'Tools that test websites and web apps for flaws.', 'Find injection, XSS, misconfiguration and outdated components that network scanners miss.', kids=[
  I('Burp Suite', 'An intercepting proxy and web testing toolkit from PortSwigger.', 'Proxy captures and edits requests; Repeater resends one by hand; Intruder sends payloads in bulk; Scanner (paid edition) finds flaws automatically.', 'Sits between your browser and the web app as a local proxy, usually on 127.0.0.1:8080.',
    flow=['Browser', '*Burp proxy', 'Web app'], trap='Modify a request and send it with payloads to see the response: that is Intruder.'),
  I('Zed Attack Proxy (ZAP)', 'OWASP&rsquo;s free, open-source intercepting proxy and scanner.', 'Does Burp&rsquo;s core jobs for free: intercept, spider, fuzz, and active and passive scans.', 'A local proxy on the tester&rsquo;s machine.'),
  I('Arachni', 'An open-source web application scanner framework (no longer maintained).', 'Crawls a site and tests forms, links, JSON and XML input for many web vulnerabilities.', 'Command line or a web interface on the tester&rsquo;s machine.'),
  I('Nikto', 'A command-line web server scanner.', 'Finds dangerous files, outdated server versions, default content and risky settings. Noisy, so it trips IDS.', 'Runs from a terminal: <code>nikto -h https://target</code>.',
    trap='Nikto finds web server weaknesses; it is not a SQL injection tool. Your job with its output is to confirm real issues and clear false positives.'),
  ]),
I('Vulnerability scanners', 'Tools that check hosts against a database of known vulnerabilities.', 'Match versions and settings to CVEs and give each finding a severity, usually a CVSS score.', kids=[
  I('Nessus', 'Tenable&rsquo;s commercial vulnerability scanner.', 'Runs plugin-based checks, credentialed or not, and reports CVEs with severity and fixes.', 'A scanner server you manage through a web interface (port 8834).'),
  I('OpenVAS', 'The open-source vulnerability scanner from Greenbone.', 'Network vulnerability checks fed by a community feed of tests.', 'A Linux scanner managed through the Greenbone web interface.'),
  ]),
I('Debuggers', 'Tools that run a program step by step so you can see its memory and registers.', 'Let you find exactly where and why software fails, and how malware behaves.', kids=[
  I('Immunity Debugger', 'A free Windows debugger with a Python API.', 'Used for exploit development and malware analysis, for example watching a buffer overflow overwrite the instruction pointer.', 'Runs on a Windows analysis machine.'),
  I('GNU Debugger (GDB)', 'The open-source command-line debugger for Linux and Unix programs.', 'Breakpoints, stepping, register and memory dumps: <code>break main</code>, <code>run</code>, <code>info registers</code>.', 'Runs in a Linux terminal: <code>gdb ./program</code>.'),
  ]),
I('Multipurpose', 'Tools that cover several assessment jobs.', 'Combine discovery, scanning, exploitation or reconnaissance.', kids=[
  I('Nmap', 'The standard network scanner.', 'Finds live hosts, open ports, service versions (<code>-sV</code>) and OS (<code>-O</code>); NSE scripts add checks.', 'Command line on the scanning host.', trap='<code>open|filtered</code> means no response came back, so Nmap can&rsquo;t tell which.'),
  I('Metasploit Framework (MSF)', 'An exploitation framework with thousands of modules.', 'Validates whether a vulnerability is really exploitable; also has scanners and post-exploitation modules.', 'Run from <code>msfconsole</code>, usually on Kali.'),
  I('Recon-ng', 'A modular OSINT reconnaissance framework.', 'Collects hosts, IPs, contacts, email addresses and social media data about a target.', 'Command line on Kali, with modules that query online sources.'),
  ]),
I('Cloud infrastructure assessment tools', 'Tools that check cloud accounts for insecure settings.', 'Find open storage, weak identity policies and missing logging in AWS, Azure and GCP.', kids=[
  I('Scout Suite', 'An open-source multi-cloud configuration auditor.', 'Produces a report of risky settings; items marked <b>Danger</b> (red) need immediate attention.', 'Runs from the analyst&rsquo;s machine using read-only cloud API credentials.'),
  I('Prowler', 'An open-source cloud security and compliance checker, strongest on AWS.', 'Runs hundreds of best-practice and compliance checks (CIS, PCI) against an account.', 'Command line using cloud API credentials.'),
  I('Pacu', 'An AWS exploitation framework.', 'Attacks an AWS account during an authorized test, the offensive counterpart to Scout Suite and Prowler.', 'Command line using AWS keys.', trap='Auditing cloud settings: Scout Suite or Prowler. Exploiting AWS in a pen test: Pacu.'),
  ]),
]}

OBJ['2.3'] = {'title': 'Given a scenario, analyze data to prioritize vulnerabilities.', 'items': [
I('Common Vulnerability Scoring System (CVSS) interpretation',
  'A standard 0&ndash;10 score for how severe a vulnerability is, written as a vector such as <code>AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H</code>.',
  'Turns a vulnerability&rsquo;s traits into a number so findings can be compared. Bands: 0.1&ndash;3.9 Low, 4.0&ndash;6.9 Medium, 7.0&ndash;8.9 High, 9.0&ndash;10 Critical.',
  'Scores come from NVD and vendors and appear on every scanner finding.',
  trap='The base score describes the flaw, not your network. A 9.8 on an isolated test box can matter less than a 7.5 on an internet-facing server.',
  kids=[
  I('Attack vectors (AV)', 'How close the attacker must be.', 'Network (N, from anywhere), Adjacent (A, same local network), Local (L, logged on), Physical (P, hands on the device). Network is worst.'),
  I('Attack complexity (AC)', 'How hard the attack is to pull off.', 'Low (L) works reliably; High (H) needs special conditions the attacker can&rsquo;t control.'),
  I('Privileges required (PR)', 'What access the attacker needs first.', 'None (N), Low (L) or High (H). None is worst.'),
  I('User interaction (UI)', 'Whether a user must do something, such as click a link.', 'None (N) or Required (R). None is worst.'),
  I('Scope (S)', 'Whether the attack can reach beyond the vulnerable component.', 'Unchanged (U) stays inside; Changed (C) affects other components, such as a VM escape reaching the host.'),
  I('Impact (C, I, A)', 'How much damage a successful attack does.', 'Rated High, Low or None for each of confidentiality, integrity and availability.', kids=[
    I('Confidentiality', 'Data being read by someone who shouldn&rsquo;t.', 'C:H means the attacker can read everything the component holds.'),
    I('Integrity', 'Data or systems being changed.', 'I:H means the attacker can modify anything.'),
    I('Availability', 'The service staying up.', 'A:H means the attacker can take it down completely.'),
    ]),
  ]),
I('Validation', 'Checking whether a scanner finding is real.', 'Separates real problems from noise before anyone spends time fixing them.', kids=[
  I('True/false positives', 'A positive is an alert. True positive: real problem. False positive: alert with no real problem.', 'False positives waste time and erode trust in the tool.', trap='After a plugin update, a new finding on every host of one app is probably a false positive. Verify before fixing or exempting it.'),
  I('True/false negatives', 'A negative is silence. True negative: nothing there. False negative: a real problem that was missed.', 'False negatives are the dangerous ones because nobody looks.'),
  ]),
I('Context awareness', 'Judging a finding by where the asset sits and who can reach it.', 'Raises or lowers priority beyond the CVSS base score.', kids=[
  I('Internal', 'Reachable only from inside your network.', 'Lower exposure, but still a target once an attacker gets in.'),
  I('External', 'Reachable from the internet.', 'Highest exposure; usually fixed first.'),
  I('Isolated', 'Air-gapped or on a separate segment with no path in.', 'Lowest exposure; often fixed later or handled with a documented exception.'),
  ]),
I('Exploitability/weaponization', 'Whether working attack code exists and how easy it is to use.', 'A flaw with a public exploit or one already used in attacks jumps the queue.', 'Check CISA&rsquo;s Known Exploited Vulnerabilities (KEV) catalog and EPSS, which estimates the chance of exploitation.'),
I('Asset value', 'How important the affected system or data is to the business.', 'The higher the asset value, the higher the priority to fix.', 'Recorded in the asset inventory and business impact analysis.'),
I('Zero-day', 'A vulnerability with no patch yet, often already being exploited.', 'Forces compensating controls (isolate, block, monitor, WAF rules) until a fix exists.', trap='Signature-based tools can&rsquo;t detect a zero-day. Answers about unknown threats want behavior-based detection.'),
]}

OBJ['2.4'] = {'title': 'Given a scenario, recommend controls to mitigate attacks and software vulnerabilities.', 'items': [
I('Cross-site scripting (XSS)', 'Attacker script that runs in another user&rsquo;s browser because a site displayed unescaped input.',
  'Steals session cookies, rewrites the page or acts as the victim.', 'Happens on the web page; the script runs in the victim&rsquo;s browser.',
  flow=['Attacker input', '*Vulnerable page', 'Victim browser runs script'],
  trap='Fix: output encoding plus input validation, and a Content Security Policy. A WAF helps but isn&rsquo;t the root fix.', kids=[
  I('Reflected', 'The script is in the request (often a link) and bounces straight back in the response.', 'Hits only whoever clicks the crafted link.'),
  I('Persistent (stored)', 'The script is saved on the server, such as in a comment, and served to everyone who views it.', 'Hits every visitor, so it is more dangerous than reflected.'),
  ]),
I('Overflow vulnerabilities', 'Writing more data than a memory area or number can hold.', 'Corrupts nearby memory; can crash the program or let an attacker run code.',
  trap='Controls: bounds checking and input validation, safe functions, DEP, ASLR, stack canaries, memory-safe languages.', kids=[
  I('Buffer', 'Copying input past the end of a fixed-size buffer.', 'Overwrites adjacent memory; the general category.'),
  I('Integer', 'Arithmetic that goes past a number type&rsquo;s maximum and wraps around.', 'Produces a tiny or negative size that later causes a buffer overflow.'),
  I('Heap', 'Overflow in memory allocated at run time.', 'Corrupts other objects or heap metadata.'),
  I('Stack', 'Overflow in a function&rsquo;s local buffer on the stack.', 'Overwrites the saved return address so execution jumps to attacker code. Stack canaries detect it.'),
  ]),
I('Data poisoning', 'Feeding bad data into what a system learns from, such as a machine learning model&rsquo;s training set.', 'Makes the model misclassify on purpose, for example letting malware pass as clean.', 'In training data pipelines and feedback loops.', trap='Control: protect and validate training data sources and monitor the model for drift.'),
I('Broken access control', 'Users can act outside their permissions.', 'Lets someone view other users&rsquo; data or reach admin functions, for example by changing an ID in the URL (IDOR).', trap='Control: check authorization on the server for every request; deny by default.'),
I('Cryptographic failures', 'Data not protected by encryption, or protected badly.', 'Exposes data through cleartext protocols, weak algorithms (MD5, DES), hard-coded keys or bad key handling.', trap='Control: TLS 1.2+ in transit, strong encryption at rest, keys in a vault or HSM, never in code.'),
I('Injection flaws', 'Untrusted input treated as part of a command or query.', 'Lets the attacker change what the interpreter runs: SQL, OS commands, LDAP, XML.', flow=['User input', '*Query built from input', 'Database runs attacker SQL'],
  trap='SQL injection fix: parameterized queries (prepared statements), plus input validation and least-privilege database accounts.'),
I('Cross-site request forgery (CSRF)', 'A trick that makes a logged-in user&rsquo;s browser send a request they didn&rsquo;t intend.', 'Performs actions as the victim, such as a transfer or password change.', 'Starts on an attacker&rsquo;s page; the browser sends the victim&rsquo;s cookies to the real site.',
  flow=['Victim logged in', 'Visits attacker page', '*Browser sends forged request', 'Real site obeys'], trap='Fix: anti-CSRF tokens (unpredictable, per request) and SameSite cookies.'),
I('Directory traversal', 'Using <code>../</code> in a file path to escape the intended folder.', 'Reads files outside the web root, such as <code>/etc/passwd</code>.', trap='Fix: validate and canonicalize paths; allow only known file names; run the service with least privilege.'),
I('Insecure design', 'Security flaws built into how the application was planned, not just bugs in code.', 'A perfect implementation is still unsafe, for example a password reset that relies on guessable questions.', trap='Fix: threat modeling and secure design reviews early in the SDLC.'),
I('Security misconfiguration', 'Insecure settings: defaults left on, verbose errors, open storage, unneeded features enabled.', 'Gives attackers easy information or access without any software bug.', trap='Fix: hardened baselines, automated configuration checks, remove what you don&rsquo;t use.'),
I('End-of-life or outdated components', 'Software or libraries that are old or no longer supported by the vendor.', 'Leaves known vulnerabilities with no patch coming.', trap='Fix: upgrade. If you can&rsquo;t, isolate it and add compensating controls. Never move it into the DMZ.'),
I('Identification and authentication failures', 'Weak proof of who a user is.', 'Allows credential stuffing, brute force and session hijacking.', trap='Fix: MFA, lockout and rate limiting, secure session handling, no default passwords.'),
I('Server-side request forgery (SSRF)', 'Tricking a server into making requests on the attacker&rsquo;s behalf.', 'Reaches internal systems the attacker can&rsquo;t, such as the cloud metadata service at <code>169.254.169.254</code>.',
  flow=['Attacker', '*Vulnerable server', 'Internal service or metadata'], trap='Fix: allowlist destinations, validate URLs, block internal and metadata addresses, require IMDSv2 in AWS.'),
I('Remote code execution (RCE)', 'An attacker can run their own code on a system over the network.', 'Gives full control: install malware, steal data, move to other systems.', trap='The worst outcome. Network-reachable RCE with no privileges or user interaction scores around 9.8 and is patched first.'),
I('Privilege escalation', 'Gaining more access than you were given.', 'Vertical: user to admin or root. Horizontal: one user to another user&rsquo;s data.', 'Through kernel bugs, misconfigured sudo or services, weak file permissions, stolen tokens.', trap='Fix: patch, least privilege, remove unneeded admin rights, monitor for new admin accounts.'),
I('Local file inclusion (LFI)/remote file inclusion (RFI)', 'A web app loads a file named in user input.', 'LFI reads or runs a file already on the server; RFI loads a file from the attacker&rsquo;s server and runs it.',
  'A parameter such as <code>?page=</code> in a PHP app.', trap='Fix: allowlist files, never pass input to include functions, and disable remote includes (<code>allow_url_include=Off</code>).'),
]}

OBJ['2.5'] = {'title': 'Explain concepts related to vulnerability response, handling, and management.', 'items': [
I('Compensating control', 'An alternative control used when the preferred one isn&rsquo;t possible.', 'Brings risk down to an acceptable level, for example isolating a server that can&rsquo;t be patched.', trap='If the ideal fix is too costly or impossible, the answer is a compensating control.'),
I('Control types', 'Ways of grouping security controls by who carries them out and what they do.', 'Helps you pick the right kind of control for a gap.', kids=[
  I('Managerial', 'Policies, risk assessments and planning: decisions on paper.', 'Directs the program, for example a security policy or awareness training plan.'),
  I('Operational', 'Day-to-day procedures carried out by people.', 'For example guards, backups and change procedures.'),
  I('Technical', 'Controls enforced by hardware or software.', 'For example firewalls, encryption and MFA.'),
  I('Preventative', 'Stops an incident before it happens.', 'For example a locked door, a firewall rule or MFA.'),
  I('Detective', 'Finds an incident while or after it happens.', 'For example IDS, log review and cameras.'),
  I('Responsive', 'Acts when an incident is detected.', 'For example an IPS blocking traffic or a SOAR playbook isolating a host.'),
  I('Corrective', 'Repairs damage and restores normal operation.', 'For example restoring from backup or reimaging.'),
  ]),
I('Patching and configuration', 'The process for fixing vulnerabilities safely.', 'Moves fixes from release to production without breaking things.',
  flow=['Test', 'Implement', 'Validate', 'Rollback if needed'], kids=[
  I('Testing', 'Trying the patch first.', 'Catches breakage in a sandbox or staging copy before it reaches production.'),
  I('Implementation', 'Deploying the patch.', 'Rolls it out through change control in a maintenance window, often in waves.'),
  I('Rollback', 'Undoing a patch that causes problems.', 'Returns to the last working state; plan it before you deploy.'),
  I('Validation', 'Confirming the fix worked.', 'A follow-up scan no longer reports the finding. A ticket marked done doesn&rsquo;t count.'),
  ]),
I('Maintenance windows', 'Agreed times when changes and reboots are allowed.', 'Limits business disruption from patching.', trap='Short or missing windows are an inhibitor to remediation.'),
I('Exceptions', 'A documented, approved decision not to fix a finding for now.', 'Records the risk owner, reason, compensating controls and a review or expiry date.', trap='An exception is not ignoring a finding. It needs approval and a review date.'),
I('Risk management principles', 'The four ways to respond to a risk.', 'Each risk gets one, chosen by cost compared with impact.', kids=[
  I('Accept', 'Live with the risk.', 'Used when fixing costs more than the risk; documented and approved.'),
  I('Transfer', 'Shift the financial impact to someone else.', 'For example cyber insurance or contracts with a provider.'),
  I('Avoid', 'Stop doing the risky activity.', 'For example retire the vulnerable service entirely.'),
  I('Mitigate', 'Reduce the likelihood or impact.', 'For example patch, harden or add controls.'),
  ]),
I('Policies, governance, and service-level objectives (SLOs)', 'The rules and targets that drive remediation.', 'Policies set deadlines by severity; governance decides who approves; SLOs are the internal target times, such as criticals fixed within 7 days.'),
I('Prioritization and escalation', 'Deciding what to fix first and when to raise it higher.', 'Uses severity, exploitability, exposure and asset value; overdue or critical items are escalated to management.'),
I('Attack surface management', 'Continuously finding and shrinking everything an attacker could target.', 'Keeps an up-to-date view of exposed assets and closes what isn&rsquo;t needed.', kids=[
  I('Edge discovery', 'Finding internet-facing assets at your network edge.', 'Reveals forgotten servers, open ports and shadow IT.'),
  I('Passive discovery', 'Finding assets without touching them.', 'Uses DNS records, certificate transparency logs and internet scan data such as Shodan.'),
  I('Security controls testing', 'Checking that controls actually work.', 'For example confirming a firewall really blocks what the policy says.'),
  I('Penetration testing and adversary emulation', 'Authorized attacks by testers.', 'Pen testing exploits weaknesses; adversary emulation copies a real threat actor&rsquo;s TTPs (from ATT&amp;CK).'),
  I('Bug bounty', 'A program that pays outside researchers for valid vulnerability reports.', 'Adds many testers under agreed rules of engagement.'),
  I('Attack surface reduction', 'Removing what isn&rsquo;t needed.', 'Close unused ports, remove services, segment networks, patch.'),
  ]),
I('Secure coding best practices', 'Habits that keep vulnerabilities out of code.', 'Prevents the 2.4 flaws at the source.', kids=[
  I('Input validation', 'Checking input against what is allowed before using it.', 'Blocks injection, overflows and traversal. Prefer allowlists, done on the server.'),
  I('Output encoding', 'Escaping data before it is displayed or passed on.', 'Stops XSS by turning <code>&lt;script&gt;</code> into harmless text.'),
  I('Session management', 'Handling session tokens safely.', 'Random tokens, Secure and HttpOnly cookies, timeouts and a new token after login.'),
  I('Authentication', 'Verifying users properly.', 'MFA, hashed and salted passwords, lockout, no hard-coded credentials.'),
  I('Data protection', 'Keeping sensitive data safe.', 'Encrypt in transit and at rest, minimize what is stored, mask what is displayed.'),
  I('Parameterized queries', 'Queries where input is passed as data, never joined into the SQL text.', 'The main fix for SQL injection.'),
  ]),
I('Secure software development life cycle (SDLC)', 'Building security into every phase of software development.', 'Requirements include security, design gets threat modeling, code gets reviews and SAST, testing gets DAST and fuzzing, and releases get scans.',
  flow=['Requirements', 'Design', 'Build', 'Test', 'Deploy', 'Maintain'], trap='Security requirements are set in the first phase, requirements gathering.'),
I('Threat modeling', 'A structured look at what could attack a system and how.', 'Finds threats and attack paths early so controls are designed in. Methods include STRIDE and attack-vector analysis.', 'Done during design, using diagrams of data flows and trust boundaries.'),
]}
